package com.opencrm.order.recovery;
import com.opencrm.order.fulfillment.EvidenceService;
import com.opencrm.order.recovery.RecoveryDtos.*;
import com.opencrm.common.order.AcceptedOrderSnapshot;
import com.opencrm.common.order.AcceptedOrderSnapshot.Line;
import com.opencrm.order.dto.OrderDtos.*;
import com.opencrm.order.domain.OrderProblem;
import com.opencrm.order.security.OrderAccess;
import com.opencrm.order.service.OrderService;
import com.opencrm.order.execution.ExecutionService;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.flywaydb.core.Flyway;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import tools.jackson.databind.json.JsonMapper;
import java.time.*;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
@Testcontainers
@Tag("integration")
class RecoveryIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 JdbcTemplate db;OrderService orders;ExecutionService execution;EvidenceService evidence;OrderAccess access;RecoveryService recovery;DailyReconciliation daily;JsonMapper json=JsonMapper.builder().build();
 @BeforeAll static void migrate(){Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).schemas("order_management").defaultSchema("order_management").load().migrate();}
 @BeforeEach void setup(){var ds=new DriverManagerDataSource(postgres.getJdbcUrl()+"&currentSchema=order_management",postgres.getUsername(),postgres.getPassword());db=new JdbcTemplate(ds);db.execute("TRUNCATE snapshot_inbox,outbox_events,execution_inbox,recovery_daily_runs CASCADE");var manager=new DataSourceTransactionManager(ds);access=mock(OrderAccess.class);when(access.actor()).thenReturn("operator");when(access.scopeId()).thenReturn("pilot");when(access.customerIds()).thenReturn(Set.of("customer"));orders=new OrderService(db,manager,json,access,true,"pilot,other-scope");execution=new ExecutionService(db,manager,json,access,true,"pilot");evidence=new EvidenceService(db,manager,json,access,execution,"pilot");recovery=new RecoveryService(db,manager,json,access,execution,"pilot");daily=new DailyReconciliation(db,manager,"pilot");}
 View order(String type){return order(type,"pilot","customer");}
 View order(String type,String scope,String customer){String unique=UUID.randomUUID().toString();var line=new Line("line","product","Widget",type,"ONE_TIME",10,"EA","10","0","0","100","ONE_TIME",null,null);var s=new AcceptedOrderSnapshot(1,unique,unique,"Q-"+unique,1,scope,customer,Instant.parse("2026-09-01T00:00:00Z"),"USD","100","0","0","100","address","approval","tax","config",List.of(line));String payload=json.writeValueAsString(s);orders.acceptTrustedSnapshot(payload,OrderService.hash(payload));var v=orders.fromQuote(new FromQuote(unique,s.quoteId(),1),"convert-"+unique);return orders.submit(v.id(),new Command(0,"go","submit-"+unique));}

 @Test void abandonmentReservesOriginalIdentityAndRejectsLateCommand(){var o=order("SERVICE");var r=recovery.abandon(o.id(),"lost",new RecoveryCommand(o.version(),"abandon","operator verified no receipt"));assertEquals("ABANDONED",r.status());assertEquals(409,assertThrows(OrderProblem.class,()->orders.hold(o.id(),new Hold(o.version(),"late","lost",true))).status());assertEquals(1,db.queryForObject("SELECT count(*) FROM recovery_command_tombstones",Integer.class));}
 @Test void existingCommandCannotBeAbandoned(){var o=order("SERVICE");assertEquals(409,assertThrows(OrderProblem.class,()->recovery.abandon(o.id(),"submit-"+o.quoteId(),new RecoveryCommand(o.version(),"abandon","no receipt"))).status());}
 @Test void unauthorizedRecoveryHasNoEffects(){var o=order("SERVICE");doThrow(new org.springframework.security.access.AccessDeniedException("denied")).when(access).require("oms:recover","pilot","customer");assertThrows(org.springframework.security.access.AccessDeniedException.class,()->recovery.abandon(o.id(),"lost",new RecoveryCommand(o.version(),"abandon","reason")));}

 String exception(View o,String category,String task){String id=UUID.randomUUID().toString();db.update("INSERT INTO order_exceptions(id,order_id,task_id,category,severity,next_action,reason) VALUES(?,?,?,?,'HIGH','RECONCILE','verified discrepancy')",id,o.id(),task,category);return id;}
 @Test void assignmentUsesExceptionVersionAndDurableReplay(){var o=order("SERVICE");String id=exception(o,"UNKNOWN_OUTCOME",null);var c=new Assignment(0,"assign","triage","owner");recovery.assign(id,c);recovery.assign(id,c);assertEquals(1,db.queryForObject("SELECT version FROM order_exceptions WHERE id=?",Long.class,id));assertEquals("SUCCEEDED",recovery.operation(id,"assign").status());assertEquals(409,assertThrows(OrderProblem.class,()->recovery.assign(id,new Assignment(0,"other","triage","owner2"))).status());}
 @Test void waiverCannotCompleteOrUnblockUnknown(){var o=order("SERVICE");String task=db.queryForObject("SELECT id FROM order_tasks WHERE order_id=? AND kind='SERVICE'",String.class,o.id());var lease=execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);execution.recordUnknown(lease,"timeout");String id=db.queryForObject("SELECT id FROM order_exceptions WHERE task_id=? AND category='UNKNOWN_OUTCOME'",String.class,task);long version=db.queryForObject("SELECT version FROM order_exceptions WHERE id=?",Long.class,id);assertEquals(409,assertThrows(OrderProblem.class,()->recovery.resolve(id,new Resolution(version,"waive","operator request","WAIVE"))).status());assertEquals(409,assertThrows(OrderProblem.class,()->recovery.resolve(id,new Resolution(version,"retry","operator request","RETRY"))).status());assertEquals("UNKNOWN",db.queryForObject("SELECT status FROM task_operations WHERE task_id=?",String.class,task));assertEquals(0,orders.get(o.id()).lines().getFirst().shipped());}
 @Test void noEffectProofEnablesSeparateStableRetry(){var o=order("SERVICE");String task=db.queryForObject("SELECT id FROM order_tasks WHERE order_id=? AND kind='SERVICE'",String.class,o.id());var lease=execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);execution.recordUnknown(lease,"timeout");var c=new NoEffect(orders.get(o.id()).version(),"proof","authoritative provider search","provider-result",Instant.now());recovery.noEffect(o.id(),task,c);recovery.noEffect(o.id(),task,c);assertEquals("RETRYABLE",db.queryForObject("SELECT status FROM task_operations WHERE task_id=?",String.class,task));assertEquals(1,db.queryForObject("SELECT count(*) FROM operation_reconciliations",Integer.class));assertEquals(lease.operationKey(),db.queryForObject("SELECT operation_key FROM task_operations WHERE task_id=?",String.class,task));}
 @Test void outboxRecoveryPreservesUuidAndAuditsAtomically(){var o=order("SERVICE");long id=db.queryForObject("SELECT min(id) FROM outbox_events",Long.class);String uuid=db.queryForObject("SELECT uuid FROM outbox_events WHERE id=?",String.class,id);db.update("UPDATE outbox_events SET exhausted_at=clock_timestamp(),retry_count=3 WHERE id=?",id);var c=new RecoveryCommand(o.version(),"requeue","broker repaired");recovery.recoverOutbox(o.id(),id,c);recovery.recoverOutbox(o.id(),id,c);assertEquals(uuid,db.queryForObject("SELECT uuid FROM outbox_events WHERE id=?",String.class,id));assertNull(db.queryForObject("SELECT exhausted_at FROM outbox_events WHERE id=?",Object.class,id));assertEquals(1,db.queryForObject("SELECT count(*) FROM order_audit WHERE action='RECOVERY_OUTBOX_REQUEUE'",Integer.class));}
 @Test void liveOutboxLeaseCannotBeRecovered(){var o=order("SERVICE");long id=db.queryForObject("SELECT min(id) FROM outbox_events",Long.class);db.update("UPDATE outbox_events SET exhausted_at=clock_timestamp(),lease_token='worker',lease_until=clock_timestamp()+interval '1 hour' WHERE id=?",id);assertEquals(409,assertThrows(OrderProblem.class,()->recovery.recoverOutbox(o.id(),id,new RecoveryCommand(o.version(),"requeue","reason"))).status());assertEquals(0,db.queryForObject("SELECT count(*) FROM recovery_receipts",Integer.class));}
 @Test void exceptionPagesFilterAccountsBeforeLimit(){var o=order("SERVICE");exception(o,"UNKNOWN_OUTCOME",null);when(access.customerIds()).thenReturn(Set.of("other-account"));var page=recovery.exceptions(0,1,null,null,null);assertEquals(0,page.totalElements());assertTrue(page.content().isEmpty());}
 @Test void dailyScanIncludesTerminalOrdersAndIsBoundedAndDurable(){var o=order("SERVICE");db.update("UPDATE orders SET status='COMPLETED' WHERE id=?",o.id());assertEquals(1,daily.scan(1));assertEquals(0,daily.scan(1));assertEquals(1,db.queryForObject("SELECT count(*) FROM recovery_findings WHERE category='TERMINAL_INCONSISTENCY'",Integer.class));assertEquals(1,db.queryForObject("SELECT scanned FROM recovery_daily_runs",Integer.class));assertEquals(0,orders.get(o.id()).lines().getFirst().remaining()==0?1:0);}
 @Test void competingOriginalAndAbandonHaveOneWinner() throws Exception {var o=order("SERVICE");try(var pool=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()){var gate=new java.util.concurrent.CountDownLatch(1);var first=pool.submit(()->{gate.await();try{orders.hold(o.id(),new Hold(o.version(),"hold","race",true));return 200;}catch(OrderProblem e){return e.status();}});var second=pool.submit(()->{gate.await();try{recovery.abandon(o.id(),"race",new RecoveryCommand(o.version(),"abandon","uncertain command"));return 200;}catch(OrderProblem e){return e.status();}});gate.countDown();assertEquals(Set.of(200,409),Set.of(first.get(),second.get()));assertEquals(1,db.queryForObject("SELECT count(*) FROM order_idempotency WHERE operation_key='race'",Integer.class));}}

 @Test void tombstoneCannotPretendToAbandonAnExternalOperation(){var o=order("SERVICE");String task=db.queryForObject("SELECT id FROM order_tasks WHERE order_id=? AND kind='SERVICE'",String.class,o.id());var lease=execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);execution.recordUnknown(lease,"timeout");assertEquals(409,assertThrows(OrderProblem.class,()->recovery.abandon(o.id(),lease.operationKey(),new RecoveryCommand(orders.get(o.id()).version(),"abandon-external","unknown effect"))).status());}
 @Test void reconciledExpiredAllocationExceptionCanCloseFromDurableRelease(){var o=order("PHYSICAL");String id=exception(o,"ALLOCATION_EXPIRED",null);recovery.resolve(id,new Resolution(0,"reconcile","verified no outstanding expired lots","RECONCILE"));assertEquals("RESOLVED",db.queryForObject("SELECT status FROM order_exceptions WHERE id=?",String.class,id));assertEquals(0,orders.get(o.id()).lines().getFirst().shipped());}
 @Test void dailyCursorAdvancesAcrossBatchesWithoutDuplicates(){for(int i=0;i<5;i++)order("SERVICE");assertEquals(2,daily.scan(2));assertEquals(2,daily.scan(2));assertEquals(1,daily.scan(2));assertEquals(0,daily.scan(2));assertEquals(5,db.queryForObject("SELECT scanned FROM recovery_daily_runs",Integer.class));assertNotNull(db.queryForObject("SELECT completed_at FROM recovery_daily_runs",Object.class));}
 @Test void dailyServiceScopeExcludesOtherDeployments(){order("SERVICE");var foreign=order("SERVICE","other-scope","customer");db.update("UPDATE orders SET status='COMPLETED' WHERE id=?",foreign.id());assertEquals(1,daily.scan(10));assertEquals(0,db.queryForObject("SELECT count(*) FROM recovery_findings",Integer.class));}
 @Test void failedFindingAuditRollsBackCursorForResume(){var o=order("SERVICE");db.update("UPDATE orders SET status='COMPLETED' WHERE id=?",o.id());db.execute("ALTER TABLE order_audit ADD CONSTRAINT reject_daily_test CHECK(action<>'DAILY_FINDING')");try{assertThrows(org.springframework.dao.DataAccessException.class,()->daily.scan(10));assertEquals(0,db.queryForObject("SELECT count(*) FROM recovery_daily_runs",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM recovery_findings",Integer.class));}finally{db.execute("ALTER TABLE order_audit DROP CONSTRAINT reject_daily_test");}assertEquals(1,daily.scan(10));}
 @Test void failedOutboxAuditRollsBackRequeue(){var o=order("SERVICE");long id=db.queryForObject("SELECT min(id) FROM outbox_events",Long.class);db.update("UPDATE outbox_events SET exhausted_at=clock_timestamp(),retry_count=3 WHERE id=?",id);db.execute("ALTER TABLE order_audit ADD CONSTRAINT reject_requeue_test CHECK(action<>'RECOVERY_OUTBOX_REQUEUE')");try{assertThrows(OrderProblem.class,()->recovery.recoverOutbox(o.id(),id,new RecoveryCommand(o.version(),"requeue","reason")));assertNotNull(db.queryForObject("SELECT exhausted_at FROM outbox_events WHERE id=?",Object.class,id));assertEquals(3,db.queryForObject("SELECT retry_count FROM outbox_events WHERE id=?",Integer.class,id));assertEquals(0,db.queryForObject("SELECT count(*) FROM recovery_receipts",Integer.class));}finally{db.execute("ALTER TABLE order_audit DROP CONSTRAINT reject_requeue_test");}}
 @Test void concurrentAssignmentsHaveOneExceptionVersionWinner() throws Exception {var o=order("SERVICE");String id=exception(o,"REVIEW_NOTE",null);try(var pool=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()){var gate=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{gate.await();try{recovery.assign(id,new Assignment(0,"a","triage","one"));return 200;}catch(OrderProblem e){return e.status();}});var b=pool.submit(()->{gate.await();try{recovery.assign(id,new Assignment(0,"b","triage","two"));return 200;}catch(OrderProblem e){return e.status();}});gate.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}}
 @Test void concurrentScannersDoNotDoubleCount() throws Exception {for(int i=0;i<5;i++)order("SERVICE");try(var pool=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()){var gate=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{gate.await();return daily.scan(3);});var b=pool.submit(()->{gate.await();return daily.scan(3);});gate.countDown();int total=a.get()+b.get();assertTrue(total<=5);daily.scan(10);assertEquals(5,db.queryForObject("SELECT scanned FROM recovery_daily_runs",Integer.class));}}
 @Test void exceptionOperationReceiptIsBoundToExceptionAndAuthorizedOrder(){var o=order("SERVICE");String a=exception(o,"REVIEW_NOTE",null),b=exception(o,"REVIEW_NOTE",null);recovery.assign(a,new Assignment(0,"assign","triage","owner"));assertEquals("NOT_FOUND",recovery.operation(b,"assign").status());doThrow(new org.springframework.security.access.AccessDeniedException("denied")).when(access).require("oms:read","pilot","customer");assertThrows(org.springframework.security.access.AccessDeniedException.class,()->recovery.operation(a,"assign"));}
 @Test void informationalWaiverDoesNotCompleteAnyTask(){var o=order("SERVICE");String id=exception(o,"REVIEW_NOTE",null);recovery.resolve(id,new Resolution(0,"waive","not material","WAIVE"));assertEquals("RESOLVED",db.queryForObject("SELECT status FROM order_exceptions WHERE id=?",String.class,id));assertEquals("SUBMITTED",orders.get(o.id()).status());assertEquals(0,db.queryForObject("SELECT count(*) FROM order_tasks WHERE status='SUCCESS'",Integer.class));}
 @Test void exhaustedPageDoesNotLeakOtherAccounts(){var o=order("SERVICE");var other=order("SERVICE","pilot","hidden");db.update("UPDATE outbox_events SET exhausted_at=clock_timestamp(),retry_count=3");var page=recovery.exhausted(0,100);assertTrue(page.totalElements()>0);assertTrue(page.content().stream().allMatch(e->e.orderId().equals(o.id())));assertTrue(page.content().stream().noneMatch(e->e.orderId().equals(other.id())));}
 @Test void tombstonesAndReceiptsAreImmutable(){var o=order("SERVICE");recovery.abandon(o.id(),"lost",new RecoveryCommand(o.version(),"abandon","verified absent"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM recovery_command_tombstones"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE recovery_receipts SET reason='changed'"));}

 @Test void assignOnlyPermissionCanAssignWithoutRecoveryPermission(){var o=order("SERVICE");String id=exception(o,"REVIEW_NOTE",null);doThrow(new org.springframework.security.access.AccessDeniedException("recover denied")).when(access).require("oms:recover","pilot","customer");recovery.assign(id,new Assignment(0,"assign-only","triage","owner"));verify(access).require("oms:assign","pilot","customer");}
 @Test void financeReconciliationUsesCumulativeExactAcknowledgments(){var o=order("SERVICE");var finance=new com.opencrm.order.finance.FinanceService(db,new DataSourceTransactionManager(db.getDataSource()),json,access,orders,execution);String line=o.lines().getFirst().id();evidence.record(o.id(),new com.opencrm.order.fulfillment.EvidenceCommand(o.version(),"service-evidence","verified service",line,"SERVICE",10,"service-complete",Instant.now(),null,null,null));finance.prepare(o.id(),line,new Command(orders.get(o.id()).version(),"prepare","prepare"));finance.acknowledge(o.id(),new com.opencrm.order.finance.FinanceDtos.Acknowledgment(orders.get(o.id()).version(),"uncertain lookup","ack-unknown",line,10,"lookup",Instant.now(),null,"UNKNOWN"));for(int i=0;i<2;i++)finance.acknowledge(o.id(),new com.opencrm.order.finance.FinanceDtos.Acknowledgment(orders.get(o.id()).version(),"actual invoice","ack-"+i,line,5,"invoice-"+i,Instant.now(),null,"ACKNOWLEDGED"));assertEquals("ACKNOWLEDGED",orders.get(o.id()).financeStatus());String id=exception(o,"FINANCE_DISCREPANCY",null);daily.scan(10);assertEquals(0,db.queryForObject("SELECT count(*) FROM recovery_findings WHERE category='FINANCE_DISCREPANCY'",Integer.class));recovery.resolve(id,new Resolution(db.queryForObject("SELECT version FROM order_exceptions WHERE id=?",Long.class,id),"finance-reconcile","exact balance confirmed","RECONCILE"));assertEquals("RESOLVED",db.queryForObject("SELECT status FROM order_exceptions WHERE id=?",String.class,id));}
 @Test void exceptionLookupCannotMixPreCommandVersionWithPostCommandReceipt(){var o=order("SERVICE");String id=exception(o,"REVIEW_NOTE",null);var fired=new java.util.concurrent.atomic.AtomicBoolean();doAnswer(invocation->{if(fired.compareAndSet(false,true))recovery.assign(id,new Assignment(0,"between-read","triage","owner"));return null;}).when(access).require("oms:read","pilot","customer");var result=recovery.operation(id,"between-read");assertEquals("SUCCEEDED",result.status());assertEquals(orders.get(o.id()).version(),result.orderVersion());}
}
